"""Build the single current rulebook from reviewed prose and a Godot rules snapshot.
Run tools/export_current_rules.gd first, then this script. No game state is changed.
"""
from pathlib import Path
import json, html, re, shutil
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, KeepTogether, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
ROOT=Path(__file__).resolve().parents[1]
D=json.loads(Path('/tmp/current-rules-data.json').read_text())
sections=[]
def section(title, intro, items): sections.append((title,intro,items))
section('1. Start here', 'Current playable rules for Ash & Oath v0.20. Prepared 30 October 2026. This is a consolidated rulebook, not a change log.', [
('Which rules does this document describe?', 'The browser prototype using Tuned numbers, with no custom numeric overrides. Optional Blank movement is described separately. The supplied draft documents inspired the game; this document describes the implemented prototype, including its declared interpretations. Older patch notes are historical.'),
('Your goal', 'Control Vesper, Rook and Wren against one chosen boss. Defeat the boss to win. If all three heroes are dead or at zero HP together, the fight ends in defeat. Against Nu’gh, defeating the summoner also removes his remaining worms.'),
('Before entering the arena', 'Choose two different bonus faces for each hero from the full 47-face bonus pool. These are faces, not whole dice. Click to quick-equip or drag them onto a die or exact slot. Each hero has a separate build and separate ownership limits. After all choices, the review screen lets you choose The Hollow, Nu’gh or the optional third boss Veyl, Tuned or Original numbers, and Blank movement OFF, Move 1 or Move 2. Check the displayed party and rules, then Enter fight.'),
('Default starting values', 'Each hero starts at 6 HP, 0 Block and 1 banked Action Reroll. The reroll bank cap is 1. The Hollow starts at 12 HP; Nu’gh starts at 10 HP with two 1-HP worms. Veyl, the Brass Cantor starts at 14 HP with 0 Resonance. The arena is a 9×9 grid. Each hero has three six-sided Action Dice. The boss occupies a 2×2 footprint.'),
('Where to look during play', 'The header names the active hero or boss and shows the round and boss intents. Click a die to read its effect in the side panel; the battlefield stays visible. Effects explains active buffs and durations. Hover a unit for its state. View dice shows every installed side, the current recorded result, and encounter mutations. Open the boss upgrade guide before or after the half-HP threshold. Full history provides detailed event ordering.')])
section('2. Dice construction and ownership', 'Limits apply to each hero individually. Do not confuse limits per die with limits across the hero’s three dice.', [
('Six sides; at least two Blanks per die', 'Each of the three dice has exactly six sides. Each die must start with at least two Blanks, leaving at most four equipped abilities. A Red Tile is a penalty face, not a Blank. There is no additional per-die category cap in the current implementation.'),
('Category caps across all three dice', 'A hero may equip at most 3 Movement faces, 3 Defense faces and 3 Skill faces in total across all three dice. Attack faces have no separate category cap, but ownership, six-side construction and minimum Blanks still restrict them. Extra Attack designs do not grant unlimited copies.'),
('Owned starting faces per hero', 'Strike ×4; Step ×2; Stride ×1; Guard ×2; Reaction ×1; Focus ×1; First Aid ×1; Shove ×1. Each of the hero’s two selected bonus designs adds one owned copy. Shove is available to build with, but is not installed in the default layout below.'),
('Default layout before bonus placement', 'Die I: Strike / Step / Guard / Strike / Blank / Blank. Die II: Strike / Stride / Reaction / Step / Blank / Blank. Die III: Strike / First Aid / Focus / Guard / Blank / Blank. Equipping bonus faces replaces existing sides as necessary to keep the build legal; inspect the final nets before entering.'),
('Changes during a fight', 'Generated faces, Engrave growth and other explicit mutations can change dice during combat; the opening construction validator is not reapplied to these effects. Mutations are for this encounter. A recorded result can remain usable even if its installed side later changes, unless the effect explicitly removes a held result. View dice distinguishes the installed side from the recorded roll. Rebuilding/retrying restores the recorded starting build.')])
section('3. Round and turn sequence', 'A round is one circuit of the initiative order. A turn is one hero’s or the boss’s activation. Dice roll together at round start, not at every normal hero turn.', [
('A. Set initiative once', 'At encounter start, each hero and the boss rolls initiative from 1 to 6. Higher goes first. The boss wins an initiative tie with a hero; hero ties use Vesper, then Rook, then Wren. This order stays fixed, except a temporary Break Rhythm delay that resets next round.'),
('B. Begin the shared round', 'Clear the previous round’s stored Reactions and Mark Prey. If a hero is still Stunned, choose a die to set aside before rolling; an actively Channeling die cannot be chosen. Roll each available Action Die once for all heroes and the boss. Held Channel dice do not roll. Reaction results automatically become held Reactions. When-rolled effects such as Clairvoyance trigger now.'),
('C. Start a hero turn', 'Expired temporary defenses clear, and ordinary old Block disappears. Stonewake is the exception that can preserve Block. Resolve an unused Echo of Pain penalty if due. Debt’s deferred penalty becomes active; the hero’s Lethargic Bind expires. Refresh that hero’s Blank-conversion allowance and Engrave growth allowance. If a Channel is active, choose Maintain or End before normal actions.'),
('D. Reroll first, if desired', 'The opening window allows a banked Action Reroll on one ready eligible die. It costs 1 charge. You keep the new result, even if it is another Blank or the same face. A reroll does not itself close the opening window. Resolving or declining an ordinary face closes it. Focus is a separate ability, explained in section 4.'),
('E. Resolve hero dice', 'Use ready immediate results in any order. Select a die, then click a legal board target or destination; use Resolve for untargeted effects. A legal resolution spends that die. Invalid targets spend nothing. Finish any pending choice or forced result before taking another ordinary action. You may end the turn with immediate dice unused; stored Reactions can still respond afterward, until the next shared roll.'),
('F. End a hero turn', 'Clear the hero’s Stunned state and unused turn-only boosts. If Black Oath is armed, pay its 1 unavoidable HP cost only if Block remains. Downed protection for all heroes ends when this full turn ends. Process queued recovery turns, then continue the initiative order.'),
('G. Take the boss turn', 'At boss turn start, The Hollow expires Chain’s Rooted and Distort and detonates armed Cinder Brand cells; then old boss Block clears. Nu’gh also clears old boss Block but has no Cinder Brand. Veyl closes any exposed core at boss turn start, then clears old Block; Resonance persists until changed by a face or spent by an attack. Resolve boss dice I → II → III. A Nu’gh Brood Command must finish all queued worms, including their Reactions, before the next boss die. Click Resolve end of turn after all three. Boss Weakness from Wither Ward expires at boss turn end. LAST ENEMY RESULT below the controls keeps fallback outcomes visible, including movement cells and Block gained.'),
('H. Start the next round', 'After the last initiative slot and any recovery turns, return to the round-start sequence. Unspent immediate results are replaced by the new shared roll. Reroll charges do not automatically refill.')])
section('4. Timing: actions, rerolls, Reactions and Channels', 'Category describes the effect family. Timing describes when it can happen. For example, Shield Wall is Defense – Reaction; Stonewake is Skill – Channel.', [
('Ordinary actions', 'Attack, Defense, Skill and Movement results usually resolve during their owner’s turn. They are spent once resolved or declined. A grey card may be spent, held as a Reaction, or held as a Channel: inspect its state label. Clicking a grey card still lets you read it.'),
('Banked Action Reroll versus Focus', 'A banked reroll uses a saved charge and only works in the opening window. Focus spends its own rolled face to reroll another READY die, and can work after other actions. Its new result must resolve next or be declined. A Reaction result is stored instead. Neither method can reroll spent/held dice, a locked Red Tile, Gambler’s Coin, Conjure or Passing Grace. Focus cannot target itself. A displayed saved charge can exist while the opening window is CLOSED.'),
('When-rolled effects', 'Clairvoyance adds a charge as soon as rolled, up to the cap; it does not wait for the hero to click Resolve. Echo of Pain arms its unused-result penalty when rolled. Contained Power can respond to other dice rolling while maintained. Repeatedly rerolling a Blank is legal; a new Blank is not evidence of a failed reroll.'),
('Reaction window', 'A held Reaction is checked before an enemy Attack applies damage, including a commanded Worm Bite. The interface pauses when its trigger is legal. Use spends it; Hold declines this opportunity while keeping the result for another eligible attack before the next shared roll. The starter Reaction grants 2 Block before the hit and never moves you. Oath of Smoke can explicitly store a Step / Stride as a movement Reaction; its stored Guard does not grant a step. Shield Wall protects an ally, Taunt and Target Override can redirect, Defy Death prevents a lethal hit, and Echo of Pain retaliates. Reactions do not normally respond to self-costs, collision damage or Brand hazards.'),
('After a Reaction changes position or target', 'A single-target Attack rechecks range and may retarget to another legal hero. Moving one hero away does not necessarily cancel the boss’s attack. Sweep, Furnace Roar and Veyl’s Toll check whether their selected victims remain in range and hit each once. Taunt and Target Override cannot redirect an entire area attack. Forced movement and a reaction step still obey their own movement restrictions.'),
('Channel start and maintenance', 'Only one Channel may be active per hero. Starting one holds its die; it does not become a normal ready result on shared rolls. At the next own turn, Maintain applies its maintained effect and keeps the die held. End releases the Channel and rolls that die immediately, including its when-rolled/Reaction handling. Starting another Channel cannot silently replace the first.'),
('Channel interruption', 'Contained Power breaks on actual HP loss, adds 2 normal backlash damage and leaves a Red Tile on its source side. Last Pulse breaks on actual HP loss and turns its source side Blank. Stonewake breaks on any HP loss or 2 cumulative Block lost within the window before the next own turn. Removing Block via a non-damage effect counts too. Block absorbing all damage does not break the first two Channels. Lethal HP loss still applies the relevant source-side mutation.'),
('Forced choices', 'Focus, Borrow Shape, copied/repeated effects and mutation picks can require a particular result or selection next. The interface pauses until that choice is complete. A failed or illegal choice does not grant a free alternate action. Choosing an ability’s target and inspecting that ability are separate from spending it.')])
section('5. Movement, targeting and damage', 'An ability’s own text takes precedence over these general procedures.', [
('Grid distance and adjacency', 'Normal distance counts orthogonal grid steps, not diagonals. Adjacent means distance 1. Distance to the 2×2 boss uses the nearest square of its footprint. Units block occupied cells. A dead worm frees its cell; a Downed but living hero still occupies theirs.'),
('Movement types', 'Step and Ashstep may turn along a clear path. Stride is a straight line and cannot turn. Leap of Echoes may jump over units but must land on an empty legal cell. Shove pushes away without collision damage. Drive Back pushes automatically along its incoming direction; players do not choose the direction. Rooted blocks voluntary moves and swaps, but not forced pushes/pulls.'),
('Line of sight and targets', 'Abilities that require sight use a straight grid ray; units can obstruct it, including worms, and blocked diagonal corners prevent shooting through. Do not assume every ability needs sight: follow its text. Several Attacks may target allies; the interface asks for confirmation. Hero healing cannot target bosses or worms. Dead heroes cannot be healed.'),
('Numeric die: what it means', 'The default ordinary Numeric die has faces 2, 2, 1, 1, 1, 0. “Roll for damage”, “rolled Block” and “heal a rolled value” mean roll this die when resolving that effect. An Action Die chooses the ability; the Numeric die determines its value. Strike deals a fixed 1 and does not roll Numeric. Strike Numeric rolls it. There is no extra default +1 bonus just for being a Numeric Attack.'),
('Damage order', 'Compute the attack’s value and relevant modifiers, then apply Weakness (minimum zero). Normal damage consumes Block first, then the remaining amount is reduced by Damage Reduction, and only the remainder removes HP. Unavoidable damage skips Block and ordinary Damage Reduction. Effects requiring HP damage only trigger if HP actually decreases. Pierce bypasses the stated amount of Block for that hit; the bypassed Block is preserved.'),
('Repeated Attacks', 'A repeat is another hit, not just doubled damage. Each hit rechecks target legality, range and any required sight; Numeric repeats roll again. A dead target stops later hits. Conditional riders such as Hooked Slash and Engrave check qualifying HP damage. Short Shot’s final per-hit cap is 2, including Mark Prey. A consumed mark or limited charge does not remain for every repeat.'),
('Gambler and Numeric modifiers', 'Gambler replaces the final two ordinary Numeric sides with ×0 and ×2. ×2 rolls an ordinary Numeric value and doubles it. ×0 is an absolute zero: boosts do not rescue it. Numeric Echo stores one ordinary value for the next Numeric roll. Focus Numeric changes the next Numeric Blank to 1. Forgotten Strength and Leap bonuses apply to the next rolled damage this turn, not fixed Strike damage.'),
('Fire is not one universal effect', 'Any positive Smoking Strike ignites its target cell, even if Block or Damage Reduction prevents HP loss. A later positive Smoking Strike on that cell consumes the fire for 2 extra normal damage (3 in phase II). Ending a hero turn on persistent fire deals 1 normal damage. Moving through fire does not detonate it; moving off before turn end avoids its burn. Zero damage after Weakness does not ignite or detonate. Cinder Brand is a separate delayed marked area that detonates at the next boss turn. Ember Burst is an immediate chosen Block-burn effect that can hurt allies and worms.')])
section('6. Status, Downed heroes and recovery', 'Read the duration on each source. “Until your next turn” is different from “until the next boss turn” or “until round end”.', [
('Block and Damage Reduction', 'Block is a consumable pool, not extra maximum HP. Old Block normally clears at the owner’s next turn start. Damage Reduction removes damage after Block and clears at the hero’s next turn start. Stonewake can preserve Block while maintained. Brood Guard’s worm shield persists until consumed; repeated shielding does not stack above its stated amount.'),
('Weakness', 'Weakness reduces Attack damage, to a minimum of zero. Distort lasts until the next boss turn start; Bulwark’s self-Weakness lasts until the hero’s next turn. When both apply, use the greater reduction, not their sum. Wither Ward gives the boss Weakness after an adjacent boss Attack actually removes HP; it lasts until the boss turn ends.'),
('Rooted', 'No voluntary movement while active, including reaction steps and Oathbound Exchange. Forced movement remains legal. Upgraded Ashen Chain applies Rooted 1 until the next boss turn begins. The sprite has a persistent root effect.'),
('Stunned', 'On application, choose an unused die to lose if one exists. If no unused die remains, the status stays visible; if still Stunned before the next shared roll, choose a non-Channel die to set aside for that roll. Gaining Stunned while already Stunned causes 1 unavoidable damage instead of granting another die choice. Stunned clears at the hero’s turn end. Orbiting stars show the current status.'),
('Weak Point, Mark Prey and Blood Bargain', 'Weak Point is personal: the next qualifying rear Attack repeats once, and the marker lasts through the end of the next round unless spent. Rear means the boss’s southern edge. Mark Prey is a boss mark, ending at the next shared round or after its next damaging hit while at zero Block. Blood Bargain empowers the next two Attacks against the boss and charges its owner 1 unavoidable damage after the second.'),
('Downed at zero HP', 'The first time a hero reaches zero HP without already being Broken, they become Downed. Their Block, Reactions, Channel and temporary effects are cleared; their reroll bank becomes zero. They cannot take normal actions. Protection prevents death from further damage for the remainder of the current full turn. After that protection ends, further positive HP damage can kill them. If everyone is Downed/dead together, defeat happens immediately.'),
('Healing a Downed hero', 'Positive healing revives them and marks them Broken. At the end of the currently active full turn, the revived hero receives a fresh, immediate recovery turn with rerolled Action Dice. Their later normal slot in that round is replaced rather than added as a second turn. Their Blank-conversion allowance refreshes for recovery, but a starting reroll is not automatically restored.'),
('Broken and dead', 'Broken means the next fall to zero HP is lethal. Dead heroes cannot act or revive during the encounter. Physical die mutations remain through Downing/revival, while temporary combat statuses do not. Retry starts a clean encounter using the saved starting build and selected rules.')])
section('7. Blank movement and custom rules', 'Optional movement is one explicit rule choice, separate from an ordinary Blank’s lack of effect.', [
('Blank movement OFF', 'A rolled Action Die Blank has no normal effect. It can be spent without moving. It is not a free Numeric roll, a reroll charge, or a movement resource.'),
('Blank → Move 1 or Move 2', 'With the Soul option ON, each hero may convert at most one rolled Action Die Blank during each of their own turns. Spend the Blank to move up to the selected distance. It still stays Blank on the installed die. Other Blanks can be spent without movement. Rooted prevents the voluntary movement. A successful conversion consumes the allowance; an invalid move does not.'),
('Exactly when it resets', 'Reset at that hero’s next normal own turn or full recovery turn. The allowance is separate for each hero. A shared round roll, reroll, Focus, or toggling the Soul OFF and ON does not refresh it. The default is one conversion, not one per die and not one per entire combat.'),
('Original preset', 'Original changes the ordinary Numeric die to 1, 1, 1, 1, 0, 0 and The Hollow to 18 HP, Smoking Strike 2, Brace 2 and its older boss dice. It also enables 1 idle fallback Block. Construction, timing and most current systems remain in place: Original is a prototype preset, not a complete recreation of every supplied draft rule. Nu’gh and Veyl keep their own boss values; the preset can still affect shared hero Numeric values. Original disables the new end-of-turn fire burn by default; the Tuned profile enables it.'),
('Advanced numeric rules', 'Open Advanced numeric rules on review, or Menu → Game options → Balance workshop. Search and change values; Apply saves the profile and restarts the current fight/test. Saved local overrides take precedence over the selected preset and this document’s defaults. Reset all values and Apply to restore that preset’s defaults. JSON imports remain a draft until applied. Applying incompatible construction limits returns you to the forge.'),
('What is saved', 'Build presets store the three heroes’ legal layouts and bonus ownership; balance profiles store numeric overrides and a base preset. These do not save a campaign or a mid-fight checkpoint. Retry preserves your selected boss and reviewed fight settings. In-fight mutations reset for the fresh encounter.')])
section('8. Practice and prototype scope', 'Use the Ability Lab to test interactions without rebuilding a normal team.', [
('Practice tools', 'The guided tutorial introduces play; the Ability Lab can prepare individual abilities, combine a second face, force Numeric values, reroll prepared results, trigger test attacks, reset and copy a reproducible log. Lab fixture HP/Block differs from ordinary encounter defaults, and has its own numeric settings.'),
('Implemented limits', 'Gold is recorded but there is no shop. Conjure and Second Chance only support the listed immediate abilities and prevent copy/repeat loops. One Channel per hero is an explicit prototype limit. The three bosses are selectable standalone fights, not a full campaign or progression economy. Generated Bone/Recovery and Red Tile are not normal bonus-pool offers.'),
('Reading an uncertain outcome', 'First inspect the exact face, active effects, reroll state and current dice net; then check Full history. A zero Numeric roll, blocked hit, same-result reroll, expired marker or closed opening window can be a legal outcome. The following catalog describes current default effects, including prototype interpretations.')])
# Detailed catalog text supplements short cards where the short version intentionally omits a choice table.
extra={30:'Ill Omen uses a d6: 1 = −1 value; 2–4 = +1 value; 5 = Pierce 2 on an Attack or +2 Block on a Defense; 6 = repeat an Attack once or double Defense Block.',32:'The stored movement Reaction steps 1; the stored Guard Reaction grants 1 Block. It expires at the next shared roll.',10:'The repeat requires an Attack against the boss from its southern edge, not merely standing behind another enemy.',15:'Passing Grace requires a recipient with a Blank; if no legal recipient slot exists, it does not destroy itself.',38:'The secondary splash applies when the main target is an enemy; attacking an ally does not trigger it.',41:'Growth fills one Blank on this die per qualifying turn, up to 3 copies; at 3 copies the attack gains +1. It cannot overwrite another ability.',46:'Defy Death automatically spends the first available unused result when applying its Stunned consequence; this is a specific exception to the usual die-choice window.',48:'The unused penalty is armed when rolled and is checked at the next own turn start; spending the Reaction disarms it.'}
for label,ids in [('9. Starting abilities',list(range(9))),('10. Bonus Skills',list(range(9,34))),('11. Bonus Attacks',list(range(34,42))),('12. Bonus Defenses',list(range(42,53))),('13. Bonus Movement and generated faces',[53,57,58,54,55,56])]:
 items=[]
 for i in ids:
  f=D['faces'][i];items.append((f["name"]+' · '+f['type'],f['description'].replace('\n\n',' ') + (' '+extra[i] if i in extra else '')))
 section(label,'Numbers below use the default Tuned profile. “Rolled” means the Numeric die in section 5.',items)
for key,title,hp in [('hollow','14. The Hollow',12),('nugh','15. Nu’gh, Worm Summoner',10)]:
 items=[]
 if key=='hollow':
  intro='12 starting HP. At 6 HP or less, phase II begins immediately and never reverses. Phase-I Brand deals 2; phase-II Brand deals 3. Sweep rises from 1 damage / reach 1 to 2 damage / reach 2. Persistent fire burns for 1 at hero turn end. The boss’s upgraded detonation deals 3 extra normal damage. Every action upgrades. Newly armed Brands use the new shape; already marked cells do not expand. Furnace Roar replaces the next unresolved boss die once, then replaces Brace on Die I in later rolls.'
 else:
  intro='10 starting HP. Nu’gh is a huge human-worm who retreats rather than chasing heroes. At 5 HP or less, Severed Brood begins immediately and never reverses, even after healing. Soul Link switches OFF permanently. Living worms add up to +1 damage to Gnashing Maw before half HP, +2 afterward. Commands, not passive pressure alone, make the brood dangerous.'
  items += [('The brood and Soul Link','Start with two 1-HP worms, up to four living at once. They occupy one cell and block movement/sight. Brood Command activates them individually: move then bite. They have no independent initiative turn and do not automatically activate at boss turn end. BEFORE half HP only, hero kills deal 1 unavoidable Soul Link damage to Nu’gh. His own consumption of a worm does not trigger Soul Link. Corpses free their cells. Summons use free legal cells within 2 of Nu’gh, preferring the front/bottom side; upgraded Burrow summons near his old location. All three heroes, including Downed heroes, the full boss footprint and living worms exclude a summon cell. Crowding or the cap can prevent a summon.'),('Why clear worms?','They make commanded attacks and feed Nu’gh’s Maw and Devour. In phase I, killing them reduces pressure and damages Nu’gh. In phase II, killing them is crowd control only: you must damage Nu’gh directly to finish him. Their deaths are not required for victory: killing Nu’gh ends the fight and removes the brood.')]
 for f in D[key]:items.append((f['name'],f['description']+' HALF-HP UPGRADE: '+f['upgrade']))
 items.append(('Boss dice, phase I',' | '.join('Die '+str(i+1)+': '+', '.join(die) for i,die in enumerate(D['dice'] if key=='hollow' else D['nugh_dice']))))
 if key=='hollow':items.append(('Fallback and targeting','A result without a valid target can use fallback: if already adjacent to a hero, hold position and gain 0 idle Block in Tuned; otherwise move 1 toward a hero, or gain 1 Block if movement fails. Tuned gives no extra idle Block just for already being adjacent. Advance has its own highest-HP/adjacent-Block rule. Read each action’s target priority; they do not all choose the same hero.'))
 else:items.append(('Command sequencing and fallback','Each Command snapshots the living brood and activates each surviving worm once. A worm moves up to 2 (3 in phase II), then bites an adjacent standing hero for 1. Reactions recheck range from that worm, not Nu’gh. Use Activate next worm, then Finish Brood Command before continuing dice. If no worms live at the start of Command, summon 2 (3 in phase II) and stop; new worms wait for a later Command. Maw with no legal target uses fallback: retreat 1 to a safer position or gain 1 Block if cornered. Results remain visible below the controls.'))
 section(title,intro,items)
cantor_items = [
 ('A different lesson: manage the shared meter', 'Veyl is a walking brass bell reliquary with a suspended blue crystal. This fight has no boss summons or terrain hazards. Resonance starts at 0 and caps at 6. Each resolved hero Attack face adds 1. Resolving an own-turn Skill or Defense face removes 1. Movement and Blanks do neither. The meter does not reset each round.'),
 ('Count faces, not hits', 'Each successfully spent face changes the meter once. A repeated Attack still adds only 1, even with several hits. A legal Attack that rolls zero still charges it. Declining a face, an invalid action, a held Reaction and maintaining a Channel do not calm or charge it. Conjure uses the final copied result’s category. The combat log names the face and exact meter change.'),
 ('Open core: a risk / reward window', 'Crescendo raises Resonance and opens Veyl’s core until its next boss turn starts. Hero Attack hits against the open core gain +1 before Block (+2 in phase II). Each repeat gets the bonus; Skill damage such as Last Word is not an Attack hit. Normal damage rules, Weakness, Short Shot’s cap and Gambler’s absolute zero still apply. Seal can add Block while the core is open, but does not close it.'),
 ('Toll declaration and Reactions', 'Toll targets every standing hero in range once. Its damage is 1 + floor(Resonance / 2), so the full meter deals 4. It spends the meter as soon as declared; the incoming hit stays fixed through Reactions. Held Reactions do not lower Resonance. Basic Reaction blocks 2 and does not move. Explicit stored movement can leave the area and avoid that hero’s hit; the Toll does not retarget everyone to one hero.'),
 ('Grand Peal at half HP', 'At 7/14 HP or less, all six actions upgrade permanently. Toll / Chime gain reach, Fork moves farther, Seal grants more Block, and notes gather more Resonance. The open-core damage bonus also rises from +1 to +2. This stronger vulnerability rewards a well-timed burst.'),
]
for f in D['cantor']:cantor_items.append((f['name'],f['description']+' HALF-HP UPGRADE: '+f['upgrade']))
cantor_items.append(('Boss dice', ' | '.join('Die '+str(i+1)+': '+', '.join(die) for i,die in enumerate(D['cantor_dice']))))
cantor_items.append(('Fallback and counterplay', 'Toll / Chime with no targets advance 1 or gain 1 Block if unable to move, keeping unspent Resonance. Tuning Fork advances before trying its hit. Read the known die order: a Gathering Note before Toll increases its eventual damage. Use Skills and Defenses to calm the meter during hero turns, and save attack bursts for an open core.'))
section('16. Veyl, the Brass Cantor', 'Optional third boss. 14 HP; half-HP threshold 7. Select Veyl on the pre-fight review screen after choosing all heroes’ faces.', cantor_items)
section('17. Quick timing reference', 'Use this page during a fight; the preceding chapters explain each rule in full.',[
('Before the shared roll','Set aside a die for any still-Stunned hero. Then roll available dice together; hold Reactions, keep Channel dice held, trigger when-rolled effects.'),
('At your turn start','Resolve due costs and expiry, refresh Blank allowance, decide Maintain/End Channel. Ordinary old Block disappears; Stonewake can preserve it.'),
('Before your first action','Optional banked reroll. A charge does not refill automatically. Locked/spent/held results cannot be selected.'),
('During your turn','Resolve ready dice in any order; finish mandatory choices first. Focus can reroll another eligible ready die after actions but forces its result next.'),
('Before an enemy Attack hits','Resolve eligible held Reactions, including for Worm Bites. Recheck targets/range from the actual attacker after movement or redirection. Starter Reaction grants 2 Block and no movement. Then apply Block → reduction → HP.'),
('At the end of a full turn','Clear Downed protection; process any queued recovery turn. Hero turn end also clears Stunned/turn boosts, applies persistent fire if occupied and checks Black Oath. Boss turn end clears its Ward Weakness.'),
('At the next boss turn start','Rooted and Distort expire, Brand detonates, then old boss Block clears. Veyl’s open core closes; its Resonance persists. Resolve new boss dice in order.'),
('At the next round','Reset temporary initiative delay, expire old Reactions and Mark Prey, and roll available dice together. This is not a new Blank-conversion allowance unless it is also that hero’s own turn.'),
('At half boss HP','Upgrade immediately once, using current maximum HP and the threshold. Healing does not return the boss to phase I. Open the phase guide for each upgraded action.')])
sections[6][2].append(('The Hollow’s Original dice', ' | '.join('Die '+str(i+1)+': '+', '.join(die) for i,die in enumerate(D['original_dice']))))
# One canonical document, with matching HTML/PDF/Markdown views.
