flow=[Paragraph('ASH & OATH',styles['RuleTitle']),Paragraph('Current Rules · v0.20',styles['RuleHead']),Paragraph('One reference for setup, turn timing, combat, all 59 faces and all three bosses.',styles['RuleIntro']),Spacer(1,16)]
for i,(title,_,_) in enumerate(sections):flow.append(Paragraph(f'<link href="#s{i}">{html.escape(title)}</link>',styles['RuleBody']))
flow.append(Spacer(1,18));flow.append(Paragraph('Default profile: Tuned, no custom overrides. Blank movement is optional. Prepared 30 October 2026. Older rulebooks and patch notes describe historical versions.',styles['RuleIntro']))
md=['# Ash & Oath — Current Rules v0.20','\nPrepared 30 October 2026. Default Tuned profile, no custom overrides.\n']
parts=['<header><p class="eyebrow">ASH &amp; OATH · v0.20</p><h1>Current rules</h1><p>Setup, timing, combat, every ability and all three bosses — in one document.</p><p>30 October 2026 · Tuned defaults, no custom overrides</p><a class="download" href="AshAndOath-Current-Rules-v0.20.pdf">Download this rulebook as PDF</a></header><nav aria-label="Contents"><h2>Contents</h2>']
for i,(title,_,_) in enumerate(sections):parts.append(f'<a href="#s{i}">{html.escape(title)}</a>')
parts.append('</nav><main>')
for i,(title,intro,items) in enumerate(sections):
 flow += [PageBreak() if i in [0,8] else Spacer(1,20),Paragraph(f'<a name="s{i}"/>'+html.escape(title),styles['RuleHead']),Paragraph(html.escape(intro),styles['RuleIntro'])]
 md += ['\n## '+title,'\n'+intro]
 parts.append(f'<section id="s{i}"><h2>{html.escape(title)}</h2><p class="intro">{html.escape(intro)}</p>')
 for head,body in items:
  flow += [Paragraph(html.escape(head),styles['RuleSub']),Paragraph(html.escape(body),styles['RuleBody'])]
  md += ['\n### '+head,'\n'+body]
  parts.append(f'<article><h3>{html.escape(head)}</h3><p>{html.escape(body)}</p></article>')
 parts.append('<a class="back" href="#top">↑ Contents</a></section>')
parts.append('</main><footer>Current rules for v0.20. Custom numeric settings override printed defaults.</footer>')
class RuleDocument(SimpleDocTemplate):
 def afterFlowable(self, flowable):
  if isinstance(flowable, Paragraph) and flowable.style.name == 'RuleHead':
   title=flowable.getPlainText();key='heading-'+str(self.seq.nextf('heading'))
   self.canv.bookmarkPage(key);self.canv.addOutlineEntry(title,key,level=0)
def footer(canvas,doc):
 canvas.setStrokeColor(colors.HexColor('#d2dddd'));canvas.line(44,40,A4[0]-44,40)
 canvas.setFont('Rules',8);canvas.setFillColor(colors.HexColor('#52606b'));canvas.drawString(44,27,'ASH & OATH  /  CURRENT RULES v0.20');canvas.drawRightString(A4[0]-44,27,str(doc.page))
RuleDocument(str(OUT/(stem+'.pdf')),pagesize=A4,rightMargin=46,leftMargin=46,topMargin=44,bottomMargin=54,title='Ash & Oath — Current Rules v0.20',author='Ash & Oath prototype').build(flow,onFirstPage=footer,onLaterPages=footer)
(OUT/'Current-Rules-v0.20.md').write_text('\n'.join(md)+'\n')
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f7f7;color:#223039;font:17px/1.7 system-ui,sans-serif}header,nav,main,footer{max-width:950px;margin:auto;padding:32px}header{padding-top:60px}.eyebrow{letter-spacing:.15em;color:#356977;font-size:14px;font-weight:700}h1{font-size:48px;line-height:1.15;margin:12px 0}h2{line-height:1.3;color:#173b47}h3{font-size:19px;line-height:1.4;margin:0 0 8px;color:#245b66}p{margin:0 0 16px}.intro{color:#53636d}nav{display:grid;grid-template-columns:1fr 1fr;gap:10px 28px;background:#e7eeee;border-radius:12px}nav h2{grid-column:1/-1;margin:0 0 12px}a{color:#1d637b;text-underline-offset:3px}section{scroll-margin-top:20px;margin-bottom:50px}article{padding:22px 26px;margin:18px 0;background:white;border:1px solid #dce4e6;border-radius:9px}article p{margin:0}.download{display:inline-block;padding:9px 18px;margin-top:8px;border-radius:6px;background:#245b66;color:white;text-decoration:none}.back{font-size:14px}footer{color:#53636d;font-size:14px}@media(max-width:650px){header,nav,main,footer{padding:22px}h1{font-size:36px}nav{grid-template-columns:1fr;border-radius:0}article{padding:18px}}@media print{nav,.download,.back{display:none}body{background:white;font-size:11pt}article{border:0;padding:0;break-inside:avoid}h2,h3{break-after:avoid}header{padding-top:0}section{break-before:page}}'''
(OUT/'current-rules.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ash & Oath — Current Rules v0.20</title><style>'+css+'</style></head><body id="top">'+''.join(parts)+'</body></html>')
for filename in [stem+'.pdf','Current-Rules-v0.20.md','current-rules.html']:shutil.copy2(OUT/filename,Path('/workspace/outputs')/filename)
